package com.ferreteriahuaman.integration;
import com.ferreteriahuaman.service.*;import com.ferreteriahuaman.repository.*;import com.ferreteriahuaman.dto.SaleModels.*;import com.ferreteriahuaman.dto.SaleModels.Details;import com.ferreteriahuaman.dto.SaleModels.Line;import com.ferreteriahuaman.dto.CashModels.Open;import com.ferreteriahuaman.dto.ProductModels.*;import com.ferreteriahuaman.dto.PurchaseModels.*;import com.ferreteriahuaman.security.AuthModels.Identity;import com.ferreteriahuaman.security.AuthFailure;import java.math.BigDecimal;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.core.env.Environment;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import static org.assertj.core.api.Assertions.*;
@SpringBootTest @ActiveProfiles({"local","db"}) @Transactional @EnabledIfEnvironmentVariable(named="HUAMAN_DB_INTEGRATION",matches="true")
class PosCustomerDatabaseTest {
 @Autowired InventoryService inventory;@Autowired SaleService service;@Autowired ProductService products;@Autowired PurchaseService purchases;@Autowired CashService cash;@Autowired CatalogService catalog;@Autowired CustomerService customers;@Autowired AuthStore auth;@Autowired Environment env;@Autowired JdbcTemplate jdbc;Identity actor;long category;String unique;BigDecimal n(String s){return new BigDecimal(s);}
 @BeforeEach void setup(){
 var current=cash.current();Assumptions.assumeTrue(current.caja()==null||current.caja().estado().equals("ABIERTA"),"No modificar una jornada ya cerrada");
 var u=auth.lockUsername(env.getProperty("BOOTSTRAP_ADMIN_USUARIO","said.astohuaman")).orElseThrow();auth.context(u.username(),"INTEGRATION_ROLLBACK");UUID token=UUID.randomUUID();auth.createSession(u.id(),token,LocalDateTime.now(ZoneId.of("America/Lima")));actor=new Identity(u.id(),u.username(),u.nombres(),u.apellidos(),u.rol(),false,auth.permissions(u.id()),token,OffsetDateTime.now().plusMinutes(30));
 unique="POS_INTEGRACION_"+UUID.randomUUID().toString().substring(0,8).toUpperCase();category=catalog.createCategory(actor,"INTEGRATION_ROLLBACK",new com.ferreteriahuaman.dto.CatalogModels.CategoryInput(unique,null,null)).id();if(current.caja()==null)cash.open(actor,"INTEGRATION_ROLLBACK",new Open(n("0"),null,UUID.randomUUID()));
 jdbc.update("update huaman.parametro_sistema set valor='Negocio de integración' where clave='NEGOCIO.RAZON_SOCIAL'");jdbc.update("update huaman.parametro_sistema set valor='20123456789' where clave='NEGOCIO.RUC'");jdbc.update("update huaman.parametro_sistema set valor='Dirección temporal 123' where clave='NEGOCIO.DIRECCION'");
 }

 Product product(String mode,String unitCode){long unit=jdbc.queryForObject("select id_unidad from huaman.unidad_medida where codigo_sunat=?",Long.class,unitCode);return products.create(actor,"INTEGRATION_ROLLBACK",new ProductInput(unique+mode.substring(0,1),"Producto "+mode,null,category,unit,true,n("0.001"),n("0.001"),mode,n("0"),null,"Base",n("10"),null));}
 long presentation(Product p){return products.details(actor,p.id()).presentaciones().getFirst().id();}
 long id(Details d){return ((Number)d.venta().get("id")).longValue();}
 Details create(long presentation,String qty,int pieces,String type,Long client){return service.create(actor,"INTEGRATION_ROLLBACK",new Create(client,type,true,UUID.randomUUID(),List.of(new Line(presentation,n(qty),pieces))));}
 long series(String type){return jdbc.queryForObject("select min(id_serie) from huaman.serie_comprobante where tipo_comprobante=? and estado='A'",Long.class,type);}
 Confirm request(Details d,List<Payment> payments,List<Assignment> assignments){return new Confirm(series(d.venta().get("tipo").toString()),LocalDateTime.parse(d.venta().get("version").toString()),payments,assignments);}
 Payment pay(String medium,String amount,String received,String operation){return new Payment(medium,n(amount),received==null?null:n(received),operation,null,null);}

 String document(){String value;do{value="20"+String.format("%09d",Math.abs(UUID.randomUUID().getLeastSignificantBits()%1000000000L));}while(count(value)>0);return value;}
 long count(String document){return jdbc.queryForObject("select count(*) from huaman.cliente where nro_documento=?",Long.class,document);}
 ClientCandidate candidate(String document){return new ClientCandidate("RUC",document,"Cliente de validación", "900000001",null,"Dirección de validación 123",new FiscalData("ACTIVO","HABIDO","150101","LIMA","LIMA","LIMA"));}
 Details draft(Product p,String document){jdbc.update("update huaman.presentacion_producto set codigo_sunat='KGM' where id_presentacion=?",presentation(p));return service.create(actor,"INTEGRATION_ROLLBACK",new Create(null,"F",true,UUID.randomUUID(),List.of(new Line(presentation(p),n("1"),1)),candidate(document)));}
 @Test void previewRetainsIdentityWithoutRegisteringCustomer(){var p=product("GRANEL","KGM");String doc=document();var d=draft(p,doc);assertThat(count(doc)).isZero();assertThat(d.venta().get("documento")).isEqualTo(doc);assertThat(d.venta().get("cliente")).isEqualTo("Cliente de validación");assertThat(d.venta().get("clienteId")).isNull();assertThat(service.details(actor,id(d)).venta().get("documento")).isEqualTo(doc);jdbc.execute("set constraints all immediate");}
 @Test void discardingDraftDoesNotRegisterCustomer(){var p=product("GRANEL","KGM");String doc=document();var d=draft(p,doc);service.discard(actor,"INTEGRATION_ROLLBACK",id(d),new Discard(UUID.randomUUID(),LocalDateTime.parse(d.venta().get("version").toString()),"Descartar escenario de integración"));assertThat(count(doc)).isZero();}
 @Test void confirmationRegistersCustomerOnceWithFiscalDetails(){var p=product("GRANEL","KGM");purchases.opening(actor,"INTEGRATION_ROLLBACK",new Opening(p.id(),n("3"),n("1"),UUID.randomUUID(),List.of()));String doc=document();var d=draft(p,doc);var req=request(d,List.of(pay("EFECTIVO","10","10",null)),List.of());var done=service.confirm(actor,"INTEGRATION_ROLLBACK",id(d),req);assertThat(count(doc)).isEqualTo(1);assertThat(done.venta().get("estado")).isEqualTo("CONFIRMADA");assertThat(done.venta().get("clientePropuesto")).isNull();assertThat(jdbc.queryForObject("select datos_identificacion->>'ubigeo' from huaman.cliente where nro_documento=?",String.class,doc)).isEqualTo("150101");service.confirm(actor,"INTEGRATION_ROLLBACK",id(d),req);assertThat(count(doc)).isEqualTo(1);jdbc.execute("set constraints all immediate");}
 @Test void failureAfterCustomerCreationRollsBackCustomerAndPayments(){var p=product("GRANEL","KGM");purchases.opening(actor,"INTEGRATION_ROLLBACK",new Opening(p.id(),n("0.5"),n("1"),UUID.randomUUID(),List.of()));String doc=document();var d=draft(p,doc);var req=request(d,List.of(pay("EFECTIVO","10","10",null)),List.of());jdbc.execute((org.springframework.jdbc.core.ConnectionCallback<Void>)connection->{var savepoint=connection.setSavepoint();try{assertThatThrownBy(()->service.confirm(actor,"INTEGRATION_ROLLBACK",id(d),req)).hasMessageContaining("Existencias insuficientes");}finally{connection.rollback(savepoint);}return null;});assertThat(count(doc)).isZero();assertThat(jdbc.queryForObject("select count(*) from huaman.pago where id_venta=?",Long.class,id(d))).isZero();}
}
